{"implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    non_removable_ids = {n['id'] for n in nodes if not n['removable']}
    retained = set(non_removable_ids)
    covered = {n['symbol'] for n in nodes if n['id'] in retained}
    for sym in required_symbols:
        if sym not in covered:
            candidates = [n for n in nodes if n['symbol'] == sym and n['id'] not in retained and n['removable']]
            if candidates:
                chosen = candidates[0]
                retained.add(chosen['id'])
                covered.add(sym)
    removed = [n['id'] for n in nodes if n['id'] not in retained]
    return {'removed_node_ids': removed, 'retained_node_ids': list(retained)}
"}
